package app.manga.source;
import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/reading-sources")public class SourceController{private final JdbcTemplate db;public SourceController(JdbcTemplate db){this.db=db;}@GetMapping("/{provider}/{mangaId}")public Object list(@PathVariable String provider,@PathVariable long mangaId){if(!provider.equalsIgnoreCase("JIKAN")||mangaId<1)throw new IllegalArgumentException("Identitas manga tidak valid.");var rows=db.queryForList("select id,source_name,source_url,source_type from reading_sources where provider=? and external_manga_id=? and verification_status='VERIFIED' and is_active=true",provider.toUpperCase(),mangaId);return Map.of("data",rows);}}
